-- Booking references are now short codes generated by the server. The client
-- idempotency key, previously embedded in the reference, gets its own column.
ALTER TABLE "bookings" ADD COLUMN "idempotencyKey" UUID;

-- Existing references ("PREFIX-" followed by the key without dashes) keep
-- replaying their original request.
UPDATE "bookings"
SET "idempotencyKey" = (
  substr("legacyKey", 1, 8) || '-' || substr("legacyKey", 9, 4) || '-' || substr("legacyKey", 13, 4) || '-'
  || substr("legacyKey", 17, 4) || '-' || substr("legacyKey", 21, 12)
)::uuid
FROM (
  SELECT "id" AS "bookingId", lower(substring("reference" FROM '^[A-Z0-9]{2,8}-([0-9A-F]{32})$')) AS "legacyKey"
  FROM "bookings"
) AS "legacy"
WHERE "legacy"."bookingId" = "bookings"."id"
  AND "legacy"."legacyKey" IS NOT NULL;

CREATE UNIQUE INDEX "bookings_idempotencyKey_key" ON "bookings"("idempotencyKey");
